    pasteDataItem(c,dx,dy,moving=false){const r=this.rawRoom();if(c.kind==='pixel'){const d=clone(c.data);d.x=clamp(Math.round((c.x+dx)*100)/100,0,W);d.y=clamp(Math.round((c.y+dy)*100)/100,0,PLAY_H);if(c.type==='decor'){d.editor_id=`decor_${this.nextDecorId++}`;r.editor_decor=r.editor_decor||[];r.editor_decor.push(d)}else{d.seed=moving?d.seed:((Number(d.seed)||Date.now())+this.nextDecorId*7919)>>>0;r.grass_clumps=r.grass_clumps||[];r.grass_clumps.push(d)}return}const tx=clamp(c.tx+dx,0,GRID_W-1),ty=clamp(c.ty+dy,0,GRID_H-1);if(c.type==='path'||c.type==='water')this.placeTile({kind:c.type},tx,ty);else if(c.type==='blocker'){this.placeTile({kind:'blocker',sprite:c.data.style?.sprite},tx,ty);r.blocker_styles[key(tx,ty)]={...c.data.style}}else if(c.type==='tree'){const sprite=c.data.tree?.sprite||c.data.style?.sprite;this.placeTile({kind:'tree',sprite},tx,ty);r.blocker_styles[key(tx,ty)]={...c.data.style,sprite:c.data.style?.sprite||sprite};const tree=(r.large_trees||[]).find(t=>t.tile?.[0]===tx&&t.tile?.[1]===ty);if(tree)tree.sprite=c.data.tree?.sprite||sprite}else if(c.type==='lamp'){const d=clone(c.data);d.tile=[tx,ty];this.replaceByTile(r.decor_lamps=r.decor_lamps||[],tx,ty,d)}else if(c.type==='robot'){const d=clone(c.data);d.tile=[tx,ty];if(!moving&&d.id)delete d.id;this.replaceByTile(r.decor_robots=r.decor_robots||[],tx,ty,d)}else if(c.type==='moth'){const d=clone(c.data);d.tile=[tx,ty];if(!moving)d.id=this.nextPersistentId('moth','editor_moth');(r.moth_pickups=r.moth_pickups||[]).push(d)}else if(c.type==='wildlife'){const d=clone(c.data);d.spawn=[tx,ty];if(!moving)d.id=this.nextPersistentId('wildlife',`editor_${d.kind||'wildlife'}`);(r.creature_groups=r.creature_groups||[]).push(d)}else if(c.type==='mini'){const d=clone(c.data);d.spawn=[tx,ty];if(!moving)d.id=this.nextPersistentId('mini',`editor_mini_${d.variant||'teal'}`);(r.mini_robot_groups=r.mini_robot_groups||[]).push(d)}}
    selectedObjective(){return this.selection.length===1&&this.selection[0].type==='objective'?this.selection[0]:null}
    toggleObjectiveVisual(){const ref=this.selectedObjective();if(!ref){this.game.toast('Select one objective in OBJECT mode.',1.5);return}const r=this.rawRoom(),hidden=new Set((r.object_fx_hidden||[]).map(String)),hide=!hidden.has(String(ref.id));this.beginTransaction(hide?'hide objective visual':'show objective visual');if(hide){r.object_fx_hidden=r.object_fx_hidden||[];if(!r.object_fx_hidden.includes(ref.id))r.object_fx_hidden.push(ref.id)}else r.object_fx_hidden=(r.object_fx_hidden||[]).filter(id=>String(id)!==String(ref.id));this.rebuildRoom();this.commitTransaction();this.game.toast(`Objective ${ref.id} visual ${hide?'hidden':'shown'} · gameplay unchanged`,1.8)}
    restoreSelectedSuppressed(){const ref=this.selection.length===1?this.selection[0]:null;if(!ref){this.game.toast('Select one suppressed item to restore.',1.5);return}const r=this.rawRoom();this.beginTransaction('restore suppressed item');let changed=false;if(ref.type==='suppressed-procedural'||ref.type==='suppressed-decor-tile')changed=RelayProceduralDecor.restore(r,ref.obj||ref.tile);else if(ref.type==='suppressed-pattern'){const before=(r.pattern_exclusions||[]).length;r.pattern_exclusions=(r.pattern_exclusions||[]).filter(id=>String(id)!==String(ref.id));changed=r.pattern_exclusions.length!==before}else if(ref.type==='objective'&&ref.hiddenVisual){const before=(r.object_fx_hidden||[]).length;r.object_fx_hidden=(r.object_fx_hidden||[]).filter(id=>String(id)!==String(ref.id));changed=r.object_fx_hidden.length!==before}if(!changed){this.cancelTransaction(false);this.game.toast('Selected item is not suppressed.',1.4);return}this.selection=[];this.rebuildRoom();this.commitTransaction();this.game.toast('Suppressed item restored.',1.3)}
    convertProceduralSelection(){const ref=this.selection.length===1?this.selection[0]:null;if(!ref||ref.type!=='procedural-decor'){this.game.toast('Select one active generated decoration to convert.',1.6);return}const d=ref.obj,r=this.rawRoom(),editorId=`decor_${this.nextDecorId++}`;this.beginTransaction('convert procedural decor');RelayProceduralDecor.suppress(r,d);r.editor_decor=r.editor_decor||[];r.editor_decor.push({editor_id:editorId,x:d.x,y:d.y,sprite:d.sprite,scale:d.scale??1,alpha:d.alpha??1,flip:!!d.flip,rot:0,element:d.element,tint_index:d.tintIndex??156,tint_strength:d.tintStrength,glow:d.glow?{dx:d.glow.x-d.x,dy:d.glow.y-d.y,element:d.glow.element,index:d.glow.index,radius:d.glow.radius,alpha:d.glow.alpha}:undefined});this.selection=[];this.rebuildRoom();const created=this.collectItems().find(it=>it.type==='decor'&&it.id===editorId);this.selection=created?[created]:[];this.commitTransaction();this.renderOverlay();this.updateStatus();this.game.toast('Generated decor converted to authored; original suppressed.',1.8)}
    updateActionButtons(){const objective=this.selectedObjective(),hidden=!!objective?.hiddenVisual,restore=this.selection.length===1&&(this.selection[0].type==='suppressed-procedural'||this.selection[0].type==='suppressed-decor-tile'||this.selection[0].type==='suppressed-pattern'||(objective&&hidden)),convert=this.selection.length===1&&this.selection[0].type==='procedural-decor',visual=root.document?.querySelector?.('#editorObjectiveVisual'),restoreBtn=root.document?.querySelector?.('#editorRestoreSuppressed'),convertBtn=root.document?.querySelector?.('#editorConvertProcedural');if(visual){visual.disabled=!objective;visual.textContent=hidden?'SHOW VISUAL':'HIDE VISUAL'}if(restoreBtn)restoreBtn.disabled=!restore;if(convertBtn)convertBtn.disabled=!convert}
    updateStatus(){this.updateActionButtons();if(!this.status)return;const h=this.historyFor();this.status.textContent=`${this.roomKey()} · ${this.tool.toUpperCase()} · ${this.choice?.label||''} · selected ${this.selection.length} · undo ${h.undo.length} · redo ${h.redo.length}${this.showSuppressed?' · SUPPRESSED VISIBLE':''}${this.clipboard?` · clipboard ${this.clipboard.items.length}`:''}`}
