    ghostGeometry(e){const centred=['moth','wildlife','mini'].includes(e.kind);let scale=e.scale??1;if(e.kind==='robot')scale=.84;else if(e.kind==='lamp')scale=.66;else if(e.kind==='moth')scale=.36;else if(e.kind==='mini')scale=1.52;else if(e.kind==='wildlife')scale=['pixie','mushroom_pixie'].includes(e.wildlifeKind)?1.62:1.755;if(!centred)scale=this.game.painter.spriteScale(e.sprite,scale);return{scale,anchor:centred?'center':'bottom',alpha:.56*(e.alpha??1)}}
