      for(const s of this.selection){c.save();c.strokeStyle='#ffe970';c.fillStyle='#ffe97018';c.lineWidth=1.8;c.setLineDash([5,3]);c.fillRect(s.bbox.x0,s.bbox.y0,s.bbox.x1-s.bbox.x0,s.bbox.y1-s.bbox.y0);c.strokeRect(s.bbox.x0+.5,s.bbox.y0+.5,s.bbox.x1-s.bbox.x0-1,s.bbox.y1-s.bbox.y0-1);c.restore()}
      if((this.dragMode==='selectBox'||this.dragMode==='objectSelectBox')&&this.dragStart&&this.dragNow){const r=rectFrom(this.dragStart,this.dragNow);c.save();c.strokeStyle='#95ffff';c.fillStyle='#5be7ff18';c.setLineDash([4,3]);c.strokeRect(r.x0,r.y0,r.x1-r.x0,r.y1-r.y0);c.fillRect(r.x0,r.y0,r.x1-r.x0,r.y1-r.y0);c.restore()}
