    async saveProject(){try{const res=await fetch('/__editor/save_maps',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(this.game.maps,null,2)+'\n'});if(!res.ok)throw new Error((await res.text())||`HTTP ${res.status}`);const data=await res.json();this.game.toast(`Saved relay_moth_maps.json · backup ${data.backup||'created'}`,2)}catch(e){this.game.toast('Project save unavailable · use Download JSON · '+e.message,3)}}
